BEGIN TRY BEGIN TRANSACTION; CREATE TABLE dbo.LocationPublicationStages(ChangeRequestId bigint NOT NULL PRIMARY KEY,LocationId int NOT NULL,StageStatus nvarchar(30) NOT NULL,ProposedJson nvarchar(max) NOT NULL,ProposedSha256 varbinary(32) NOT NULL,GeocodeStatus nvarchar(20) NOT NULL,DuplicateReviewStatus nvarchar(20) NOT NULL,RowVersion rowversion NOT NULL,CONSTRAINT FK_Candidate_StageRequest FOREIGN KEY(ChangeRequestId) REFERENCES dbo.ChangeRequests(ChangeRequestId),CONSTRAINT CK_Candidate_StageJson CHECK(ISJSON(ProposedJson)=1),CONSTRAINT CK_Candidate_StageStatus CHECK(StageStatus IN(N'PendingGeocode',N'ReadyForPublish',N'Published',N'Abandoned'))); CREATE TABLE dbo.LocationPublishedVersions(LocationPublishedVersionId bigint IDENTITY PRIMARY KEY,LocationId int NOT NULL,VersionNumber int NOT NULL,ChangeRequestId bigint NULL,IsCurrent bit NOT NULL,PublishedJson nvarchar(max) NOT NULL,PublishedAt datetime2(3) NOT NULL,CONSTRAINT UX_Candidate_CurrentVersion UNIQUE(LocationId,VersionNumber),CONSTRAINT FK_Candidate_PublishedRequest FOREIGN KEY(ChangeRequestId) REFERENCES dbo.ChangeRequests(ChangeRequestId)); INSERT dbo.SchemaVersions(VersionNumber,Description,AppliedAt,AppliedBy) VALUES(N'1.8.0-014',N'R3 candidate 1800_014',SYSUTCDATETIME(),N'candidate-rehearsal'); COMMIT; SELECT N'UP_OK' Result,N'1.8.0-014' Marker; END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK; THROW; END CATCH;